INSERT INTO `after_sale_policy` (`policy_name`, `category`, `condition_type`, `min_amount`, `max_amount`, `min_reputation`, `action`, `reply_template`, `priority`, `enabled`) VALUES
                                                                                                                                                                                   ('小额退款自动通过', 'REFUND', 'AMOUNT_REPUTATION', 0.00, 50.00, 80, 'AUTO_APPROVE', '尊敬的客户，您的退款申请已自动审核通过，退款将在1-3个工作日内到账。感谢您的耐心等待。', 1, 1),
                                                                                                                                                                                   ('中额退款人工审核', 'REFUND', 'AMOUNT_REPUTATION', 50.00, 500.00, 60, 'AUTO_REPLY', '尊敬的客户，您的退款申请已收到，我们将在24小时内为您处理。如有疑问请随时联系我们。', 2, 1),
                                                                                                                                                                                   ('大额退款直接转人工', 'REFUND', 'AMOUNT', 500.00, 99999.00, 0, 'MANUAL', '尊敬的客户，您的退款金额较大，已转交专人处理，我们将在2小时内与您联系。', 3, 1),
                                                                                                                                                                                   ('物流异常自动查询', 'LOGISTICS', 'ALWAYS', 0.00, 99999.00, 0, 'AUTO_REPLY', '尊敬的客户，我们已为您查询物流信息，物流状态显示您的包裹正在运输中，请耐心等待。如有异常我们会及时通知您。', 1, 1),
                                                                                                                                                                                   ('物流延迟自动补偿', 'LOGISTICS', 'AMOUNT_REPUTATION', 0.00, 99999.00, 70, 'AUTO_APPROVE', '尊敬的客户，非常抱歉给您带来不便，我们将为您补偿10元优惠券，请注意查收。', 2, 1),
                                                                                                                                                                                   ('商品破损自动退款(小额)', 'DAMAGE', 'AMOUNT_REPUTATION', 0.00, 200.00, 70, 'AUTO_APPROVE', '尊敬的客户，非常抱歉您收到的商品有破损，退款已自动审核通过，同时我们会改进包装。', 1, 1),
                                                                                                                                                                                   ('商品破损人工处理(大额)', 'DAMAGE', 'AMOUNT', 200.00, 99999.00, 0, 'AUTO_REPLY', '尊敬的客户，您的商品破损情况我们已记录，客服专员将在2小时内与您联系处理。', 2, 1),
                                                                                                                                                                                   ('发票问题自动回复', 'INVOICE', 'ALWAYS', 0.00, 99999.00, 0, 'AUTO_REPLY', '尊敬的客户，发票相关问题我们将在1个工作日内为您处理，请注意查收邮件。', 1, 1);
INSERT INTO `ticket` (`ticket_no`, `user_id`, `agent_id`, `order_id`, `title`, `description`, `category`, `status`, `priority`, `sla_deadline`) VALUES
                                                                                                                                                    ('TK20240001', 4, 2, 1, 'iPhone屏幕有划痕', '收到的iPhone 15 Pro Max屏幕有明显划痕，要求退货退款', 'DAMAGE', 'MANUAL_REVIEW', 'HIGH', '2024-02-20 12:00:00'),
                                                                                                                                                    ('TK20240002', 5, NULL, 2, 'MacBook充电器不兼容', '购买的MacBook Pro充电器与国内插座不兼容，需要换货', 'OTHER', 'AI_PROCESSING', 'MEDIUM', '2024-02-20 14:00:00'),
                                                                                                                                                    ('TK20240003', 6, 3, 3, 'AirPods降噪效果差', '购买的AirPods Pro降噪效果不如宣传的好，要求退货', 'REFUND', 'RESOLVED', 'LOW', '2024-02-19 16:00:00'),
                                                                                                                                                    ('TK20240004', 4, NULL, 4, 'iPad物流一周未更新', 'iPad订单已发货一周，物流信息一直未更新', 'LOGISTICS', 'PENDING', 'MEDIUM', '2024-02-21 10:00:00'),
                                                                                                                                                    ('TK20240005', 5, 2, 5, 'Apple Watch表带断裂', 'Apple Watch Ultra 2的表带使用两天就断裂了', 'DAMAGE', 'MANUAL_REVIEW', 'HIGH', '2024-02-20 18:00:00');
INSERT INTO `ticket_message` (`ticket_id`, `user_id`, `sender_type`, `message_type`, `content`) VALUES
                                                                                                    (1, 4, 'USER', 'TEXT', '你好，我收到的iPhone屏幕有划痕，明显是质量问题，我要退货退款'),
                                                                                                    (1, 0, 'AI', 'AI_REPLY', '您好，非常抱歉给您带来不好的体验。已为您查询到订单ORD20240001，iPhone 15 Pro Max。关于屏幕划痕问题，我们建议您先拍照上传作为凭证，我们会尽快为您处理。是否需要为您转接人工客服？'),
                                                                                                    (1, 2, 'AGENT', 'TEXT', '您好王先生，我是客服张三，已收到您的反馈。请您提供一下划痕的照片，我们会优先为您处理。'),
                                                                                                    (2, 5, 'USER', 'TEXT', '我买的MacBook充电器是英标插头，没法在国内用，怎么换货？'),
                                                                                                    (2, 0, 'AI', 'AI_REPLY', '您好，已为您查询到订单ORD20240002。关于充电器插头不兼容的问题，我们可以为您安排换货。换货流程大约需要3-5个工作日。请问您是否同意换货？'),
                                                                                                    (3, 6, 'USER', 'TEXT', 'AirPods Pro降噪效果很差，根本不像宣传的那样，我要退货'),
                                                                                                    (3, 0, 'AI', 'AI_REPLY', '您好，已为您查询到订单ORD20240003。您的信誉良好，退款申请已自动审核通过。退款将在1-3个工作日内原路退回。'),
                                                                                                    (4, 4, 'USER', 'TEXT', '我的iPad订单已经一周了，物流信息一直不更新，到底怎么回事？'),
                                                                                                    (5, 5, 'USER', 'TEXT', 'Apple Watch的表带用了两天就断了，这是什么质量？要求退款');
